INSERT INTO `products` (`product_id`, `product_name`, `price`, `product_img`, `product_desc`, `category_id`, `stock`, `created_at`, `updated_at`) VALUES
(5, 'Americano', '150.00', 'product_6912964a5e2409.55733899.png', 'Americano', 1, 20, '2025-11-11 17:50:02', '2025-11-11 17:50:02'),
(6, 'Affogato', '100.00', 'product_69129ccc7a9570.51906915.png', 'affogato is an Italian dessert made by pouring a shot of hot espresso over a scoop of cold vanilla ice cream or gelato.', 1, 30, '2025-11-11 18:17:48', '2025-11-11 18:17:48'),
(7, 'Black Coffee', '90.00', 'product_69129eefdcc3c0.77333053.png', 'Black coffee is a simple beverage made by brewing coffee grounds in water with no added milk, cream, or sugar.', 1, 50, '2025-11-11 18:26:55', '2025-11-11 18:26:55'),
(8, 'Brown Sugar Latte', '110.00', 'product_69129f491a2517.37196033.png', 'A brown sugar latte is a coffee beverage made with espresso, milk, and brown sugar syrup or a homemade brown sugar sauce.', 1, 50, '2025-11-11 18:28:25', '2025-11-11 18:28:25'),
(9, 'Cafe au Lait', '130.00', 'product_69129f997eeb03.87744796.png', 'A cafÃ© au lait is a French coffee drink made with equal parts hot brewed coffee and steamed milk. Unlike a latte, it uses regular brewed coffee instead of espresso and traditionally has little to no foam. ', 1, 30, '2025-11-11 18:29:45', '2025-11-11 18:29:45'),
(10, 'Cafe Bombon', '100.00', 'product_6912a5520b1464.49650437.png', 'CafÃ© BombÃ³n is a Spanish coffee drink made of equal parts strong espresso and sweetened condensed milk, creating a rich, sweet, and bitter balance that is often layered in a glass to show off the distinct colors before mixing. ', 1, 20, '2025-11-11 18:54:10', '2025-11-11 18:54:10'),
(12, 'Cafe Breve', '100.00', 'product_6912a6e3674291.76414163.png', 'A caffÃ¨ breve is an American-style espresso drink made with steamed half-and-half (half milk, half cream) instead of milk, which gives it a richer, creamier, and naturally sweeter taste compared to a standard latte. ', 1, 20, '2025-11-11 19:00:51', '2025-11-11 19:00:51'),
(13, 'Cafe Con Leche', '100.00', 'product_6912a71fd0f991.79603885.png', 'CafÃ© con leche is a Spanish coffee drink made with strong coffee (traditionally espresso) and hot, scalded milk, usually in equal parts.', 1, 20, '2025-11-11 19:01:51', '2025-11-11 19:01:51'),
(14, 'Cafe Cubano', '100.00', 'product_6912a77b0fd3f3.60150617.png', 'CafÃ© Cubano is a strong, sweet espresso-style coffee from Cuba made by brewing dark-roasted coffee grounds with demerara sugar.', 1, 20, '2025-11-11 19:03:23', '2025-11-11 19:03:23'),
(15, 'Cafe de Olla', '99.00', 'product_6912a8329cc1d3.37085344.png', 'CafÃ© de olla is a traditional Mexican coffee, historically brewed in a clay pot (olla de barro), with a unique flavor profile from cinnamon and piloncillo (unrefined cane sugar).', 1, 20, '2025-11-11 19:06:26', '2025-11-11 19:06:26'),
(16, 'Cafe Miel', '90.00', 'product_6912a8bf5edeb0.87303381.png', 'Miel is a delicious Spanish coffee drink that originated in Spain. It combines coffee, steamed milk (or frothed cold milk for iced) and a drizzle of honey. ', 1, 30, '2025-11-11 19:08:47', '2025-11-11 19:08:47'),
(17, 'Cappuccino', '120.00', 'product_6912a90b5db672.84534609.png', 'A cappuccino is an Italian coffee drink with three equal parts of espresso, steamed milk, and frothed milk foam.', 1, 40, '2025-11-11 19:10:03', '2025-11-11 19:10:03'),
(19, 'Caramel Macchiato', '120.00', 'product_6912e8c629d923.48374687.png', 'A caramel macchiato is a coffee drink made with steamed milk, vanilla syrup, and espresso, topped with a caramel drizzle.', 1, 30, '2025-11-11 23:41:58', '2025-11-11 23:41:58'),
(20, 'Cinnamon Latte', '110.00', 'product_6912e9265c9a25.46553900.png', 'A cinnamon latte is a coffee beverage made with espresso, steamed milk, and cinnamon-flavored syrup, often topped with whipped cream and a sprinkle of cinnamon.', 1, 40, '2025-11-11 23:43:34', '2025-11-11 23:43:34'),
(21, 'Coconut Latte', '99.00', 'product_6912e9d54590b6.73250459.png', 'A coconut latte is a coffee drink made with espresso and coconut milk, which provides a creamy texture and a sweet, tropical flavor.', 1, 35, '2025-11-11 23:46:29', '2025-11-11 23:46:29'),
(22, 'Cold Brew', '79.00', 'product_6912ea4e5e9261.27853763.png', 'Cold brew is coffee made by steeping coarse coffee grounds in cold or room-temperature water for 12 to 24 hours, resulting in a concentrate that is smooth, less acidic, and can be served over ice, mixed with milk, or diluted with water.', 1, 30, '2025-11-11 23:48:30', '2025-11-11 23:48:30'),
(23, 'Cortado', '90.00', 'product_6912eac5a71628.70963736.png', 'A cortado is a Spanish coffee drink made with equal parts espresso and lightly steamed milk, creating a balanced and smooth beverage. ', 1, 40, '2025-11-11 23:50:29', '2025-11-11 23:50:29'),
(24, 'Dalgona Coffee', '110.00', 'product_6912eb53df78c0.43482256.png', 'Dalgona coffee is a whipped, frothy coffee drink made from instant coffee, sugar, and hot water whipped to a creamy foam, then served over hot or cold milk.', 1, 40, '2025-11-11 23:52:51', '2025-11-11 23:52:51'),
(25, 'Espresso Con Panna', '110.00', 'product_6912ee35bc5674.13061214.png', 'Espresso con panna is an Italian drink meaning \"espresso with cream,\" consisting of a shot or two of espresso topped with a dollop of whipped cream.', 1, 50, '2025-11-12 00:05:09', '2025-11-12 00:05:09'),
(26, 'Espresso', '100.00', 'product_6912eea7587a12.82272141.png', 'Espresso is a concentrated coffee made by forcing hot water under high pressure through finely-ground coffee beans.', 1, 60, '2025-11-12 00:07:03', '2025-11-12 00:07:03'),
(27, 'Flat White', '120.00', 'product_6912ef1df0a206.78185359.png', 'A flat white is an espresso-based drink made with a double shot of espresso and a thin, \"flat\" layer of steamed milk with a velvety microfoam texture.', 1, 40, '2025-11-12 00:09:01', '2025-11-12 00:09:01'),
(28, 'Hazalnut Latte', '130.00', 'product_6912ef8ba342a5.61909381.png', 'A hazelnut latte is a warm coffee drink made with espresso, steamed milk, and hazelnut flavoring, resulting in a smooth, nutty, and creamy beverage.', 1, 30, '2025-11-12 00:10:51', '2025-11-12 00:10:51'),
(30, 'Honey Oat Latte', '100.00', 'product_6912f2cdbf7117.05928010.png', 'A Honey Oat Latte is a creamy coffee beverage made with espresso, steamed oat milk, and honey. ', 1, 30, '2025-11-12 00:24:45', '2025-11-12 00:24:45'),
(31, 'Iced Americano', '120.00', 'product_6912f33a453d27.97505262.png', 'An iced americano is a refreshing cold coffee drink made by combining espresso shots with cold water and ice. It is a simple, black coffee drink with a strong espresso flavor that is diluted by the cold water and melted ice.', 1, 20, '2025-11-12 00:26:34', '2025-11-12 00:26:34'),
(32, 'Iced Caramel Latte', '130.00', 'product_6912f38d40c542.09661832.png', 'An iced caramel latte is a chilled coffee drink made with a blend of espresso, cold milk, and a sweet caramel syrup or sauce, served over ice.', 1, 60, '2025-11-12 00:27:57', '2025-11-12 00:27:57'),
(33, 'Iced Hazelnut Latte', '120.00', 'product_6912f4f3e61bd5.87925583.png', 'An Iced Hazelnut Latte is a cold coffee drink made with espresso, chilled milk, and hazelnut syrup, creating a smooth, creamy, and sweet nutty beverage.', 1, 40, '2025-11-12 00:33:55', '2025-11-12 00:33:55'),
(34, 'Iced Latte', '110.00', 'product_6912f52e0c7137.06116647.png', 'An iced latte is a cold coffee beverage made with espresso, cold milk, and ice, creating a creamier, richer taste than iced coffee.', 1, 11, '2025-11-12 00:34:54', '2025-11-12 00:34:54'),
(35, 'Iced Matcha Latte', '120.00', 'product_6912f65c941ae2.02094073.png', 'An iced matcha latte is a refreshing, creamy beverage made from matcha green tea powder, milk, and a sweetener, served over ice.', 1, 50, '2025-11-12 00:39:56', '2025-11-12 00:39:56'),
(36, 'Iced Mocha', '110.00', 'product_6912f74d86d838.15853377.png', 'An iced mocha is a cold, coffee-based drink made with espresso, chocolate syrup, and milk poured over ice.', 1, 40, '2025-11-12 00:43:57', '2025-11-12 00:43:57'),
(37, 'Iced Vanilla Latte', '150.00', 'product_6912f7a9e3ada1.91009986.png', 'An Iced Vanilla Latte is a cold coffee beverage made from espresso, milk, and vanilla syrup, served over ice.', 1, 30, '2025-11-12 00:45:29', '2025-11-12 00:45:29'),
(38, 'Irish Coffee', '100.00', 'product_6912f800084883.87148911.png', 'Irish coffee is a hot cocktail made with hot coffee, Irish whiskey, sugar, and topped with a layer of cream. ', 1, 20, '2025-11-12 00:46:56', '2025-11-12 00:46:56'),
(39, 'Latte', '80.00', 'product_6912f84989cda8.59856514.png', 'A latte is an espresso-based drink made with one or two shots of espresso, a larger amount of steamed milk, and topped with a thin layer of frothed milk.', 1, 30, '2025-11-12 00:48:09', '2025-11-12 00:48:09'),
(40, 'Lungo', '100.00', 'product_6912f87b79c978.87660786.png', 'A lungo is an Italian espresso drink made by using the same amount of coffee grounds as a standard espresso but forcing more hot water through them, resulting in a longer, larger, and milder coffee with a more bitter taste.', 1, 20, '2025-11-12 00:48:59', '2025-11-12 00:48:59'),
(41, 'Macchiato', '110.00', 'product_6912f8e04bc824.23036044.png', 'A macchiato is an espresso drink \"marked\" with a small amount of foamed or steamed milk, creating a strong coffee flavor with a hint of creaminess.', 1, 30, '2025-11-12 00:50:40', '2025-11-12 00:50:40'),
(42, 'Matcha Latte', '120.00', 'product_6912f90fb1a4f2.65923906.png', 'A matcha latte is a creamy, vibrant green beverage made from finely ground green tea powder (matcha), hot water, and frothed milk, often served hot or iced.', 1, 50, '2025-11-12 00:51:27', '2025-11-12 00:51:27'),
(43, 'Mocha', '140.00', 'product_6912f996db90d3.06894647.png', 'A mocha is an espresso-based coffee drink that combines coffee with chocolate, typically made with espresso, steamed milk, and chocolate syrup or powder.', 1, 40, '2025-11-12 00:53:42', '2025-11-12 00:53:42'),
(44, 'Nitro Cold Brew', '110.00', 'product_6912f9ed1c3c93.52144241.png', 'Nitro cold brew is cold brew coffee infused with nitrogen gas, which gives it a creamy, velvety-smooth texture and a foamy head, similar to a stout beer.', 1, 40, '2025-11-12 00:55:09', '2025-11-12 00:55:09'),
(45, 'Pumpkim Spice Latte', '90.00', 'product_6913051f751a05.07092315.png', 'A Pumpkin Spice Latte (PSL) is a coffee drink made with espresso, steamed milk, and a blend of spices like cinnamon, nutmeg, and clove.', 1, 20, '2025-11-12 01:42:55', '2025-11-12 01:42:55'),
(46, 'Red Eye', '110.00', 'product_69130562ba3fc7.82011772.png', 'A Red Eye is a coffee drink made by adding a shot of espresso to a standard cup of drip coffee for an extra caffeine boost.', 1, 20, '2025-11-12 01:44:02', '2025-11-12 01:44:02'),
(47, 'Ristretto', '100.00', 'product_691305bf25c696.08521474.png', 'Ristretto is an Italian coffee term for \"restricted,\" meaning a short, concentrated shot of espresso made with less hot water than a regular espresso.', 1, 25, '2025-11-12 01:45:35', '2025-11-12 01:45:35'),
(48, 'Spanish Latte', '130.00', 'product_691306e195bb14.98705855.png', 'A Spanish latte is an espresso-based drink made with espresso, steamed milk, and sweetened condensed milk, which makes it richer and sweeter than a regular latte.', 1, 53, '2025-11-12 01:50:25', '2025-11-12 01:50:25'),
(49, 'Spanish Mocha', '140.00', 'product_6913071b1f0aa9.40090032.png', 'A Spanish mocha is a rich coffee drink made with espresso, condensed milk, and chocolate, which provides a sweeter, creamier profile than a regular mocha.', 1, 30, '2025-11-12 01:51:23', '2025-11-12 01:51:23'),
(50, 'Tiramisu Latte', '150.00', 'product_69130778168aa1.21927225.png', 'A Tiramisu Latte is a coffee drink inspired by the classic Italian dessert, combining espresso with tiramisu flavors like mascarpone cream, chocolate, and a dusting of cocoa.', 1, 36, '2025-11-12 01:52:56', '2025-11-12 01:52:56'),
(51, 'Toffee Nut Latte', '160.00', 'product_691307b4d66204.02995852.png', 'A Toffee Nut Latte is a warm, sweet coffee beverage made with espresso, steamed milk, and a toffee nut syrup that provides a rich, buttery, and nutty flavor.', 1, 42, '2025-11-12 01:53:56', '2025-11-12 01:53:56'),
(52, 'Turkish Coffee', '110.00', 'product_691307e6b77e49.29725095.png', 'Turkish coffee is a strong, unfiltered brew made from very finely ground coffee beans, water, and often sugar, which is simmered in a pot called a cezve.', 1, 25, '2025-11-12 01:54:46', '2025-11-12 01:54:46'),
(53, 'Vanilla Latte', '120.00', 'product_6913081ad4ac85.49228812.png', 'A vanilla latte is a coffee drink made with espresso, steamed milk, and vanilla syrup.', 1, 45, '2025-11-12 01:55:38', '2025-11-12 01:55:38'),
(54, 'Vietnamese Coffee', '100.00', 'product_69130847f1a839.88193121.png', 'Vietnamese coffee is a strong, dark-roast coffee made from beans grown in Vietnam, traditionally brewed with a metal drip filter called a phin.', 1, 45, '2025-11-12 01:56:23', '2025-11-12 01:56:23'),
(55, 'White Mocha', '149.00', 'product_6913088d5c8865.37173683.png', 'A white mocha is a coffee drink made with espresso, steamed milk, and white chocolate syrup or sauce. It offers a sweet, creamy, and indulgent flavor profile, with white chocolate replacing the dark chocolate found in a traditional mocha.', 1, 30, '2025-11-12 01:57:33', '2025-11-12 01:57:33'),
(56, 'Caramel Frappe', '130.00', 'product_69130caea2eba9.29254677.png', 'A caramel frappe is a blended, iced coffee drink with a sweet, creamy, and smooth consistency, made with coffee, milk, and caramel syrup, then topped with whipped cream and a caramel drizzle.', 3, 30, '2025-11-12 02:15:10', '2025-11-12 02:15:10'),
(57, 'Chocolate Frappe', '130.00', 'product_69130ce4813f15.36392712.png', 'A chocolate frappe is a blended, icy, and creamy drink made with milk, chocolate flavorings (like syrup or cocoa), and ice, often topped with whipped cream and extra chocolate toppings.', 3, 30, '2025-11-12 02:16:04', '2025-11-12 02:16:04'),
(58, 'Coffee Frappe', '130.00', 'product_69130d0da10209.73403976.png', 'A coffee frappe is a blended, cold, and frothy coffee drink that can be made by combining coffee, milk, sugar, and ice, then shaken or blended until it\'s thick and creamy.', 3, 20, '2025-11-12 02:16:45', '2025-11-12 02:16:45'),
(59, 'Cookies and Cream Frappe', '150.00', 'product_69130d5d267fc8.70478465.png', 'FrappuccinoÂ® Roast coffee, mocha sauce and FrappuccinoÂ® chips blended with milk and ice, layered on top of whipped cream and chocolate cookie crumble and topped with vanilla whipped cream, mocha drizzle and even more chocolate cookie crumble.', 3, 25, '2025-11-12 02:18:05', '2025-11-12 02:18:05'),
(60, 'Espresso Frappe', '130.00', 'product_69130d99d246b2.20282672.png', 'An espresso frappe is a blended, iced coffee drink made with espresso, milk, and ice, often sweetened and topped with whipped cream and sauces.', 3, 30, '2025-11-12 02:19:05', '2025-11-12 02:19:05'),
(61, 'Hazelnut Frappe', '140.00', 'product_69130de7d5b381.61296317.png', 'A hazelnut frappe is a blended, icy coffee drink featuring a rich, nutty hazelnut flavor, typically made with coffee, milk, ice, and hazelnut syrup.', 3, 40, '2025-11-12 02:20:23', '2025-11-12 02:20:23'),
(62, 'Matcha Frappe', '145.00', 'product_69130e23b82781.16483983.png', 'A Matcha FrappÃ© is a blended, iced beverage that combines the earthy, rich flavor of matcha green tea with creamy milk and ice, creating a sweet and refreshing treat.', 3, 35, '2025-11-12 02:21:23', '2025-11-12 02:21:23'),
(63, 'Mocha Frappe', '130.00', 'product_69130e4fae9749.32905950.png', 'A mocha frappe is a blended, icy coffee drink with a rich, chocolatey flavor from a mix of coffee, milk, ice, and chocolate syrup or cocoa powder.', 3, 30, '2025-11-12 02:22:07', '2025-11-12 02:22:07'),
(64, 'Oreo Frappe', '135.00', 'product_69130e86713e61.43350537.png', 'An Oreo frappe is a blended iced coffee drink made with milk, ice, and crushed Oreo cookies, often including chocolate syrup and a coffee flavor.', 3, 30, '2025-11-12 02:23:02', '2025-11-12 02:23:02'),
(65, 'Strawberry Frappe', '160.00', 'product_69130ebc7a8706.98921368.png', 'A strawberry frappe is a cold, blended beverage made with ice, milk, and strawberry puree or syrup, topped with whipped cream. It\'s a sweet, creamy, and refreshing drink with a distinct strawberry flavor.', 3, 45, '2025-11-12 02:23:56', '2025-11-12 02:23:56'),
(66, 'Vanilla Frappe', '140.00', 'product_69130ee8bf7bb7.24542738.png', 'A vanilla frappe is a blended iced beverage made with vanilla, milk, and ice, often topped with whipped cream.', 3, 35, '2025-11-12 02:24:40', '2025-11-12 02:24:40'),
(67, 'White Mocha Frappe', '120.00', 'product_69130f163709c0.82596026.png', 'A White Mocha Frappe is a blended, iced coffee drink with a creamy, sweet flavor from white chocolate syrup mixed with coffee, milk, and ice.', 3, 30, '2025-11-12 02:25:26', '2025-11-12 02:25:26'),
(68, 'Avocado Shake', '110.00', 'product_6913106e8a25d8.38970405.png', 'Avocado shakes are refreshing and easy to make. Simply blend avocados with coconut milk. Layer with crushed ice, sweetened condensed milk, and a sprinkling of toasted coconut.', 4, 50, '2025-11-12 02:31:10', '2025-11-12 02:31:10'),
(69, 'Banana Shake', '110.00', 'product_691315063f0f03.69770544.png', 'Banana Shake is basically a sweetened drink made by blending ripe bananas, milk, ice cream, flavorings and a sweetener. ', 4, 30, '2025-11-12 02:50:46', '2025-11-12 02:50:46'),
(70, 'Black Forest Shake', '120.00', 'product_6913157337f796.70620226.png', 'A Black Forest Shake is a rich, creamy dessert drink inspired by the classic German Black Forest cake (Black Forest gateau). It combines the signature flavors of chocolate and cherries, typically in a smooth, sippable form.', 4, 30, '2025-11-12 02:52:35', '2025-11-12 02:52:35'),
(71, 'Blueberry Shake', '150.00', 'product_691315a73cd118.55554136.png', 'A blueberry shake is a creamy, sweet, and thick drink made by blending blueberries with milk and a sweetener, typically vanilla ice cream.', 4, 25, '2025-11-12 02:53:27', '2025-11-12 02:53:27'),
(72, 'Butterscotch Shake', '130.00', 'product_691315e9764c82.07353199.png', 'made with vanilla ice cream and ribboned with sweet, decadent butterscotch sauce for a shake with well-balanced flavours. The butterscotch sauce, which is made with butter and caramelized brown sugar, is rich and sweet and goes perfectly with the creamy vanilla ice cream.', 4, 45, '2025-11-12 02:54:33', '2025-11-12 02:54:33'),
(73, 'Caramel Shake', '120.00', 'product_691316488aa3b5.08439612.png', 'A caramel shake is a creamy, smooth, and indulgent frozen drink with a rich, buttery, and sweet flavor profile. It is typically made by blending vanilla ice cream, milk (often whole milk for thickness), and a generous amount of caramel sauce until smooth.', 4, 50, '2025-11-12 02:56:08', '2025-11-12 02:56:08'),
(74, 'Cheesecake Shake', '160.00', 'product_69131679a7f7a8.74009189.png', 'A Cheesecake Shake is a rich, creamy, and indulgent blended drink that captures all the classic flavors and textures of a traditional cheesecake dessert in a portable, sippable form. It offers a unique balance of a sweet and slightly tangy flavor profile.', 4, 40, '2025-11-12 02:56:57', '2025-11-12 02:56:57'),
(75, 'Chocolate Peanut Butter Shake', '130.00', 'product_691316bea08ba1.80800433.png', 'A Chocolate Peanut Butter Shake is a rich, creamy, and indulgent blended beverage that delivers the classic and beloved combination of robust chocolate and nutty peanut butter flavors. It is essentially a frosty, drinkable dessert that offers a perfect balance of sweet and salty. ', 4, 50, '2025-11-12 02:58:06', '2025-11-12 02:58:06'),
(76, 'Chocolate Shake', '120.00', 'product_6913171c6c83f9.73638321.png', 'A Chocolate Shake is a classic, rich, creamy, and indulgent blended beverage that delivers a deep, satisfying cocoa flavor in a smooth, thick, and frosty form. It is a timeless, popular treat that serves as a liquid dessert for chocolate lovers.', 4, 30, '2025-11-12 02:59:40', '2025-11-12 02:59:40'),
(77, 'Coconut Shake', '120.00', 'product_69131789497934.39836718.png', 'A Coconut Shake is a creamy, rich, and intensely refreshing blended tropical beverage. It is widely popular in Southeast Asia (where it is often known as Buko Shake in the Philippines) as a cooling treat on a hot day. It captures the essence of a beach vacation in a glass.', 4, 45, '2025-11-12 03:01:29', '2025-11-12 03:01:29'),
(78, 'Coffee Shake', '130.00', 'product_691317af566408.02183783.png', 'A Coffee Shake is a robust and invigorating blended beverage that combines the rich, aromatic flavor of coffee with the creamy texture of a classic milkshake. It provides a unique balance of a refreshing, frosty treat and the caffeinated kick of a traditional cup of coffee.', 4, 20, '2025-11-12 03:02:07', '2025-11-12 03:02:07'),
(79, 'Cookies and Cream Shake', '150.00', 'product_691317efb827a1.01439142.png', 'A Cookies and Cream Shake is a classic, indulgent milkshake that blends a creamy vanilla base with crushed chocolate sandwich cookies (most commonly Oreos). It is cherished for its contrasting and satisfying combination of smooth, rich \"cream\" flavor and delightful \"cookie\" crunch. \r\nKey ', 4, 50, '2025-11-12 03:03:11', '2025-11-12 03:03:11'),
(80, 'Dark Chocolate Shake', '160.00', 'product_69131827b05f42.50940329.png', 'A Dark Chocolate Shake is a rich, decadent, and intensely flavored blended beverage that focuses on the deep, complex notes of high-cocoa chocolate, typically with less sweetness than a standard milk chocolate shake.', 4, 40, '2025-11-12 03:04:07', '2025-11-12 03:04:07'),
(81, 'Mango Shake', '120.00', 'product_69131867307e64.86439096.png', 'A Mango Shake is a bright, vibrant, and highly refreshing blended fruit drink that is a popular treat, especially in tropical regions during the peak of mango season. It is known for its distinctly sweet, juicy, and aromatic tropical flavor.', 4, 30, '2025-11-12 03:05:11', '2025-11-12 03:05:11'),
(82, 'Matcha Shake', '130.00', 'product_6913189376fd90.84738617.png', 'A Matcha Shake is a distinctively flavored, vibrant green, creamy blended beverage that merges the earthy, slightly vegetal, and robust notes of Japanese matcha green tea powder with a sweet, rich base, such as ice cream or milk.', 4, 30, '2025-11-12 03:05:55', '2025-11-12 03:05:55'),
(83, 'Melon Shake', '120.00', 'product_691318ca8f60f6.40874187.png', 'A Melon Shake is a light, creamy, and exceptionally refreshing blended beverage that highlights the sweet, aromatic, and juicy flavors of fresh melon, most commonly cantaloupe or honeydew. It\'s a popular choice as a thirst-quencher, particularly during warm weather.', 4, 50, '2025-11-12 03:06:50', '2025-11-12 03:06:50'),
